public int[] maxSlidingWindow(int[] nums, int k) {
    int n = nums.length;
    int[] res = new int[n - k + 1];
    Deque<Integer> dq = new ArrayDeque<>();       // indices, values decreasing
    for (int i = 0; i < n; i++) {
        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();
        dq.offerLast(i);
        if (dq.peekFirst() <= i - k) dq.pollFirst();
        if (i >= k - 1) res[i - k + 1] = nums[dq.peekFirst()];
    }
    return res;
}

public int shortestSubarray(int[] nums, int k) {
    int n = nums.length;
    long[] prefix = new long[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];
    int res = n + 1;
    Deque<Integer> dq = new ArrayDeque<>();       // prefix indices, prefix values increasing
    for (int i = 0; i <= n; i++) {
        while (!dq.isEmpty() && prefix[i] - prefix[dq.peekFirst()] >= k)
            res = Math.min(res, i - dq.pollFirst());
        while (!dq.isEmpty() && prefix[dq.peekLast()] >= prefix[i]) dq.pollLast();
        dq.offerLast(i);
    }
    return res <= n ? res : -1;
}

public int constrainedSubsetSum(int[] nums, int k) {
    int n = nums.length;
    int[] dp = new int[n];
    Deque<Integer> dq = new ArrayDeque<>();       // indices, dp values decreasing
    int res = Integer.MIN_VALUE;
    for (int i = 0; i < n; i++) {
        while (!dq.isEmpty() && dq.peekFirst() < i - k) dq.pollFirst();
        int best = dq.isEmpty() ? 0 : Math.max(0, dp[dq.peekFirst()]);
        dp[i] = nums[i] + best;
        res = Math.max(res, dp[i]);
        while (!dq.isEmpty() && dp[dq.peekLast()] <= dp[i]) dq.pollLast();
        dq.offerLast(i);
    }
    return res;
}

public int maxResult(int[] nums, int k) {
    int n = nums.length;
    int[] dp = new int[n];
    dp[0] = nums[0];
    Deque<Integer> dq = new ArrayDeque<>();       // indices, dp values decreasing
    dq.offerLast(0);
    for (int i = 1; i < n; i++) {
        while (!dq.isEmpty() && dq.peekFirst() < i - k) dq.pollFirst();
        dp[i] = nums[i] + dp[dq.peekFirst()];
        while (!dq.isEmpty() && dp[dq.peekLast()] <= dp[i]) dq.pollLast();
        dq.offerLast(i);
    }
    return dp[n - 1];
}

public int largestRectangleArea(int[] heights) {
    int n = heights.length;
    Deque<Integer> stack = new ArrayDeque<>();    // indices, heights increasing
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && heights[stack.peek()] >= h) {
            int height = heights[stack.pop()];
            int left = stack.isEmpty() ? -1 : stack.peek();
            int width = i - left - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack.push(i);
    }
    return maxArea;
}

public int findMaxValueOfEquation(int[][] points, int k) {
    Deque<int[]> dq = new ArrayDeque<>();         // {y - x, x}, first value decreasing
    int res = Integer.MIN_VALUE;
    for (int[] p : points) {
        int x = p[0], y = p[1];
        while (!dq.isEmpty() && dq.peekFirst()[1] < x - k) dq.pollFirst();
        if (!dq.isEmpty()) res = Math.max(res, dq.peekFirst()[0] + y + x);
        while (!dq.isEmpty() && dq.peekLast()[0] <= y - x) dq.pollLast();
        dq.offerLast(new int[]{y - x, x});
    }
    return res;
}

public int minMeetingRooms(int[][] intervals) {
    int n = intervals.length;
    int[] starts = new int[n];
    int[] ends = new int[n];
    for (int i = 0; i < n; i++) { starts[i] = intervals[i][0]; ends[i] = intervals[i][1]; }
    Arrays.sort(starts);
    Arrays.sort(ends);
    int rooms = 0, maxRooms = 0, e = 0;
    for (int s = 0; s < n; s++) {
        while (e < n && ends[e] <= starts[s]) { rooms--; e++; }
        rooms++;
        maxRooms = Math.max(maxRooms, rooms);
    }
    return maxRooms;
}

class MyCalendar {                                     // I: no double booking
    private final TreeMap<Integer, Integer> cal = new TreeMap<>(); // start -> end
    public boolean book(int start, int end) {
        Integer prev = cal.floorKey(start);
        Integer next = cal.ceilingKey(start);
        if (prev != null && cal.get(prev) > start) return false;
        if (next != null && next < end) return false;
        cal.put(start, end);
        return true;
    }
}

class MyCalendarTwo {                                  // II: no triple booking
    private final TreeMap<Integer, Integer> delta = new TreeMap<>();
    public boolean book(int start, int end) {
        delta.merge(start, 1, Integer::sum);
        delta.merge(end, -1, Integer::sum);
        int active = 0;
        for (int v : delta.values()) {
            active += v;
            if (active >= 3) {                         // would triple-book: roll back
                delta.merge(start, -1, Integer::sum);
                delta.merge(end, 1, Integer::sum);
                return false;
            }
        }
        return true;
    }
}

class MyCalendarThree {                                // III: max k-booking
    private final TreeMap<Integer, Integer> delta = new TreeMap<>();
    public int book(int start, int end) {
        delta.merge(start, 1, Integer::sum);
        delta.merge(end, -1, Integer::sum);
        int active = 0, max = 0;
        for (int v : delta.values()) { active += v; max = Math.max(max, active); }
        return max;
    }
}

public int rectangleArea(int[][] rectangles) {
    final long MOD = 1_000_000_007L;
    TreeSet<Integer> xsSet = new TreeSet<>();
    for (int[] r : rectangles) { xsSet.add(r[0]); xsSet.add(r[2]); }
    Integer[] xs = xsSet.toArray(new Integer[0]);
    Map<Integer, Integer> xIdx = new HashMap<>();
    for (int i = 0; i < xs.length; i++) xIdx.put(xs[i], i);

    // event: {y, delta(+1 bottom / -1 top), xStartIdx, xEndIdx}
    List<int[]> events = new ArrayList<>();
    for (int[] r : rectangles) {
        events.add(new int[]{r[1], 1, xIdx.get(r[0]), xIdx.get(r[2])});
        events.add(new int[]{r[3], -1, xIdx.get(r[0]), xIdx.get(r[2])});
    }
    events.sort((a, b) -> Integer.compare(a[0], b[0]));

    int[] count = new int[xs.length];             // coverage per slab i: [xs[i], xs[i+1])
    long area = 0;
    long prevY = events.get(0)[0];
    for (int[] e : events) {
        long y = e[0];
        long width = 0;
        for (int i = 0; i + 1 < xs.length; i++)
            if (count[i] > 0) width += xs[i + 1] - xs[i];
        area = (area + (width % MOD) * ((y - prevY) % MOD)) % MOD;
        for (int i = e[2]; i < e[3]; i++) count[i] += e[1];
        prevY = y;
    }
    return (int) area;
}

public List<int[]> employeeFreeTime(int[][][] schedule) {
    List<int[]> all = new ArrayList<>();
    for (int[][] emp : schedule) for (int[] iv : emp) all.add(iv);
    all.sort((a, b) -> a[0] - b[0]);

    List<int[]> free = new ArrayList<>();
    int prevEnd = all.get(0)[1];
    for (int i = 1; i < all.size(); i++) {
        int[] iv = all.get(i);
        if (iv[0] > prevEnd) free.add(new int[]{prevEnd, iv[0]});   // gap = free time
        prevEnd = Math.max(prevEnd, iv[1]);
    }
    return free;
}

public int countOfAirplanes(List<int[]> flights) {
    List<int[]> events = new ArrayList<>();
    for (int[] f : flights) {
        events.add(new int[]{f[0], 1});     // takeoff
        events.add(new int[]{f[1], -1});    // landing
    }
    // ties: landing (-1) before takeoff (+1)
    events.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
    int cur = 0, max = 0;
    for (int[] e : events) { cur += e[1]; max = Math.max(max, cur); }
    return max;
}

public List<List<Long>> splitPainting(int[][] segments) {
    TreeMap<Integer, Long> delta = new TreeMap<>();
    for (int[] s : segments) {
        delta.merge(s[0],  (long) s[2], Long::sum);
        delta.merge(s[1], -(long) s[2], Long::sum);
    }
    List<List<Long>> res = new ArrayList<>();
    long sum = 0;
    Integer prev = null;
    for (Map.Entry<Integer, Long> e : delta.entrySet()) {
        int point = e.getKey();
        if (prev != null && sum > 0) {
            if (!res.isEmpty() && res.get(res.size() - 1).get(1) == (long) (int) prev
                    && res.get(res.size() - 1).get(2) == sum)
                res.get(res.size() - 1).set(1, (long) point);          // merge equal-sum span
            else
                res.add(new ArrayList<>(List.of((long) prev, (long) point, sum)));
        }
        sum += e.getValue();
        prev = point;
    }
    return res;
}

public int[] minInterval(int[][] intervals, int[] queries) {
    Arrays.sort(intervals, (a, b) -> a[0] - b[0]);
    Integer[] order = new Integer[queries.length];
    for (int i = 0; i < queries.length; i++) order[i] = i;
    Arrays.sort(order, (a, b) -> queries[a] - queries[b]);

    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]); // [size, end]
    int[] res = new int[queries.length];
    int i = 0;
    for (int qi : order) {
        int q = queries[qi];
        while (i < intervals.length && intervals[i][0] <= q) {
            int size = intervals[i][1] - intervals[i][0] + 1;
            pq.offer(new int[]{size, intervals[i][1]});
            i++;
        }
        while (!pq.isEmpty() && pq.peek()[1] < q) pq.poll();   // end < q => invalid
        res[qi] = pq.isEmpty() ? -1 : pq.peek()[0];
    }
    return res;
}
